#[test]
fn override_policy_channels_devices_process_kernel_apply_exactly() {
    let mut c = InstanceConfig::parse(VALID.as_bytes()).unwrap();
    c.apply_override(b"contract.devices.read", b"[\"/dev/null\"]").unwrap();
    assert_eq!(c.device_read.as_slice().len(), 1);
    assert_eq!(c.device_read.as_slice()[0].as_bytes(), b"/dev/null");
    c.apply_override(b"contract.devices.write", b"[\"/dev/zero\"]").unwrap();
    assert_eq!(c.device_write.as_slice().len(), 1);
    c.apply_override(b"contract.devices.create", b"[\"/dev/custom\"]").unwrap();
    assert_eq!(c.device_create.as_slice().len(), 1);
    assert!(c.filesystem_device_nodes);
    c.apply_override(b"contract.process.signals", b"[\"signal.kill\"]").unwrap();
    assert_eq!(c.process_signals.as_slice().len(), 1);
    c.apply_override(b"contract.kernel.proc_read", b"[\"/proc/**\"]").unwrap();
    assert_eq!(c.kernel_proc_read.as_slice().len(), 1);
    assert_eq!(c.kernel_proc_read.as_slice()[0].as_bytes(), b"/proc/**");
}

#[test]
fn parse_field_duplicate_detection_pins_contract_allow_deny_bits() {
    let dup_allow = VALID.replace("allow = []", "allow = []\nallow = [\"syscall.clock_*\"]");
    assert_eq!(
        InstanceConfig::parse(dup_allow.as_bytes()),
        Err(ConfigError::DuplicateField)
    );
    let dup_deny = VALID.replace("deny = []", "deny = []\ndeny = [\"syscall.mount*\"]");
    assert_eq!(
        InstanceConfig::parse(dup_deny.as_bytes()),
        Err(ConfigError::DuplicateField)
    );
    // single occurrence still parses cleanly
    assert!(InstanceConfig::parse(VALID.as_bytes()).is_ok());
}

#[test]
fn index_is_empty_and_resolve_link_length_boundary_are_exact() {
    // empty index: len 0, is_empty true
    let mut header = [0u8; HEADER_SIZE];
    encode_header(0, &mut header);
    let empty = Index::new(&header).unwrap();
    assert_eq!(empty.len(), 0);
    assert!(empty.is_empty());
    // non-empty index: is_empty false
    let bytes = index_bytes();
    let index = Index::new(&bytes).unwrap();
    assert!(!index.is_empty());
    assert!(index.len() > 0);
    // symlink whose target length equals MAX_PATH exactly: accepted by the copy gate
    let mut buf = [0u8; HEADER_SIZE + 2 * RECORD_SIZE];
    encode_header(2, (&mut buf[..HEADER_SIZE]).try_into().unwrap());
    let root = Entry {
        path: b"/", kind: NodeKind::Directory, mode: 0o755,
        uid: 0, gid: 0, size: 0, data_offset: 0, link: b"",
    };
    encode_record(root, (&mut buf[HEADER_SIZE..HEADER_SIZE + RECORD_SIZE]).try_into().unwrap()).unwrap();
    let long_target = [b'a'; MAX_PATH];
    let link_entry = Entry {
        path: b"/l", kind: NodeKind::Symlink, mode: 0o777,
        uid: 0, gid: 0, size: 0, data_offset: 0, link: &long_target,
    };
    encode_record(link_entry, (&mut buf[HEADER_SIZE + RECORD_SIZE..]).try_into().unwrap()).unwrap();
    let idx = Index::new(&buf).unwrap();
    // exact-fit link copies without InvalidPath; resolution then fails NotFound
    assert_eq!(idx.resolve(b"/l"), Err(VfsError::NotFound));
}

